const stateMiddleware = (req, res, next) => {
  const url = new URL(req.url, 'http://localhost'); const sid = url.searchParams.get('sid');
  const reply = data => { res.setHeader('Content-Type', 'application/json'); res.setHeader('Cache-Control', 'no-cache'); res.end(JSON.stringify(data)); };
  if (url.pathname === '/state' && req.method === 'GET') { const state = sessions.get(sid)?.current || null; reply({ stored_state: state, has_custom_state: state !== null, sid }); return; }
  if (url.pathname !== '/post' || req.method !== 'POST') return next();
  if (!sid) { res.statusCode = 400; reply({ error: 'sid required' }); return; }
  let body = ''; req.on('data', chunk => { body += chunk; }); req.on('end', () => {
    try { const { action, state } = JSON.parse(body);
      if (action === 'set') sessions.set(sid, { initial: structuredClone(state), current: state });
      else if (action === 'set_current' && sessions.has(sid)) sessions.get(sid).current = state;
      else if (action === 'reset') sessions.delete(sid);
      else { res.statusCode = 400; reply({ error: 'Unknown action or session' }); return; }
      reply({ success: true });
    } catch (e) { res.statusCode = 400; reply({ error: e.message }); }
  });
};

