export function getSessionId() {
  // Internal navigation drops the query string, and every other hub clone remembers the sid in
  // sessionStorage for exactly that reason. Without this, one click on a nav link moves the worker
  // off the company's session onto the shared `default` one: every later write lands there and
  // every later page renders the shipped demo records.
  const params = new URLSearchParams(window.location.search);
  const sid = params.get('sid');
  if (sid) {
    try { sessionStorage.setItem('westlaw_sid', sid); } catch (e) { /* ignore */ }
    return sid;
  }
  try { return sessionStorage.getItem('westlaw_sid') || 'default'; } catch (e) { /* ignore */ }
  return 'default';
}

