export async function initializeData(sid) {
  const custom = await fetchCustomState(sid);
  if (custom) return custom;
  const initial = createInitialData();
  // Claim a baseline only when the server says this session has none. A company-sized world is
  // megabytes and every navigation refetches it, so a read that was aborted or failed must leave
  // the seeded world alone instead of replacing it with these demo records.
  try {
    const res = await fetch(`/state?sid=${sid}`);
    const data = res.ok ? await res.json() : null;
    if (!data || data.has_custom_state) return (data && data.stored_state) || initial;
    await fetch(`/post?sid=${sid}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'set', state: initial })
    });
  } catch (e) {
    // ignore
  }
  return initial;
}

